import zipfile, re, sys
from xml.etree import ElementTree as ET

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
path = 'sales_data.xlsx'

with zipfile.ZipFile(path) as z:
    names = z.namelist()
    print("ENTRIES:", names)
    shared = []
    if 'xl/sharedStrings.xml' in names:
        root = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in root.findall('m:si', NS):
            shared.append(''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t')))
    print("SHARED STRINGS:", shared)
    wbroot = ET.fromstring(z.read('xl/workbook.xml'))
    sheets = [s.get('name') for s in wbroot.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}sheet')]
    print("SHEETS:", sheets)
    for sheet in sheets:
        idx = sheets.index(sheet) + 1
        rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
        rid = None
        for rel in rels:
            if rel.get('Target') == 'worksheets/sheet%d.xml' % idx:
                rid = rel.get('Id')
        # simpler: find the sheet file matching
        target = None
        for rel in rels:
            if rel.get('Type', '').endswith('worksheet'):
                t = rel.get('Target')
                if t.startswith('worksheets/sheet') and t == 'worksheets/sheet%d.xml' % idx:
                    target = t
        if target is None:
            for rel in rels:
                if rel.get('Type', '').endswith('worksheet'):
                    target = rel.get('Target')
                    break
        print("\n--- SHEET:", sheet, "FILE:", target)
        root = ET.fromstring(z.read('xl/' + target))
        for c in root.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}c'):
            ref = c.get('r')
            t = c.get('t')
            v = c.find('m:v', NS)
            val = v.text if v is not None else None
            if t == 's' and val is not None:
                val = shared[int(val)]
            if val is not None:
                print(ref, repr(val))

import zipfile, shutil, os, sys
from xml.etree import ElementTree as ET

M = '{http://schemas.openxmlformats.org/spreadsheetml/2006/main}'
SRC = 'sales_data.xlsx'
TMP = 'sales_data_tmp.xlsx'
SHEET_FILE = 'xl/worksheets/sheet1.xml'

def col_letter(ref):
    return ''.join(ch for ch in ref if ch.isalpha())

def cell_text(c):
    is_el = c.find(M + 'is')
    if is_el is not None:
        return ''.join(t.text or '' for t in is_el.iter(M + 't'))
    v = c.find(M + 'v')
    return v.text if v is not None else None

with zipfile.ZipFile(SRC) as z:
    root = ET.fromstring(z.read(SHEET_FILE))
    rows = {r.get('r'): r for r in root.iter(M + 'row')}

needed = {}  # ref -> (kind, value)
for rn in ['2', '3', '4', '5', '6', '7', '8', '9', '10']:
    row = rows.get(rn)
    if row is None:
        needed['H' + rn] = ('formula', 'IFERROR(G%s/E%s,0)' % (rn, rn))
        continue
    h = None
    for c in row.findall(M + 'c'):
        if col_letter(c.get('r')) == 'H':
            h = c
            break
    if h is None:
        needed['H' + rn] = ('formula', 'IFERROR(G%s/E%s,0)' % (rn, rn))
    else:
        f = h.find(M + 'f')
        if f is None or f.text != 'IFERROR(G%s/E%s,0)' % (rn, rn):
            needed['H' + rn] = ('formula', 'IFERROR(G%s/E%s,0)' % (rn, rn))

hdr = rows.get('1')
h1 = None
if hdr is not None:
    for c in hdr.findall(M + 'c'):
        if col_letter(c.get('r')) == 'H':
            h1 = c
            break
if h1 is None or cell_text(h1) != 'Profit Margin %':
    needed['H1'] = ('header', 'Profit Margin %')

if not needed:
    print('OK: Profit Margin % column already present and correct (header + IFERROR(Gn/En,0) formulas, rows 2-10). No changes required.')
    sys.exit(0)

print('MISSING:', needed)

def make_cell(ref, kind, value):
    c = ET.Element(M + 'c', {'r': ref})
    if kind == 'header':
        c.set('s', '1')
        c.set('t', 'inlineStr')
        is_el = ET.SubElement(c, M + 'is')
        t = ET.SubElement(is_el, M + 't')
        t.text = value
    else:
        c.set('s', '3')
        f = ET.SubElement(c, M + 'f')
        f.text = value
    return c

for ref, (kind, value) in needed.items():
    rn = ref[1:]
    row = rows.get(rn)
    if row is None:
        row = ET.Element(M + 'row', {'r': rn})
        root.find(M + 'sheetData').append(row)
        rows[rn] = row
    # insert in column order
    existing = [col_letter(c.get('r')) for c in row.findall(M + 'c')]
    newc = make_cell(ref, kind, value)
    inserted = False
    for c in list(row.findall(M + 'c')):
        if col_letter(c.get('r')) > 'H':
            row.insert(list(row).index(c), newc)
            inserted = True
            break
    if not inserted:
        row.append(newc)

dim = root.find(M + 'dimension')
if dim is not None:
    dim.set('ref', 'A1:H10')

ET.register_namespace('', 'http://schemas.openxmlformats.org/spreadsheetml/2006/main')
xml_out = ET.tostring(root, encoding='UTF-8', xml_declaration=True)

with zipfile.ZipFile(SRC) as zin, zipfile.ZipFile(TMP, 'w', zipfile.ZIP_DEFLATED) as zout:
    for item in zin.infolist():
        data = xml_out if item.filename == SHEET_FILE else zin.read(item.filename)
        zout.writestr(item, data)
shutil.move(TMP, SRC)
print('UPDATED sales_data.xlsx with Profit Margin % column (header + formulas).')

